from collections import defaultdict, deque


class _Cell:
    """Base class for reactive cells."""

    def __init__(self):
        self._value = None
        self._inputs = []
        self._dependents = []
        self._callbacks = []

    @property
    def value(self):
        return self._value

    def add_dependent(self, dependent):
        self._dependents.append(dependent)

    def _compute(self):
        raise NotImplementedError

    def _propagate(self):
        """Recompute every downstream cell so the system reaches a new
        stable state, then fire callbacks for cells whose value changed."""
        # Collect every downstream cell affected by this change.
        affected = []
        seen = set()
        stack = list(self._dependents)
        while stack:
            cell = stack.pop()
            if cell in seen:
                continue
            seen.add(cell)
            affected.append(cell)
            stack.extend(cell._dependents)

        if not affected:
            return

        # Topologically order the affected cells (Kahn's algorithm) so that
        # a cell's inputs are recomputed before the cell itself.
        affected_set = set(affected)
        indegree = {
            cell: sum(1 for dep in cell._inputs if dep in affected_set)
            for cell in affected
        }
        adjacency = defaultdict(list)
        for cell in affected:
            for dep in cell._inputs:
                if dep in affected_set:
                    adjacency[dep].append(cell)

        order = []
        queue = deque(cell for cell in affected if indegree[cell] == 0)
        while queue:
            cell = queue.popleft()
            order.append(cell)
            for dependent in adjacency[cell]:
                indegree[dependent] -= 1
                if indegree[dependent] == 0:
                    queue.append(dependent)

        # Recompute in order, remembering which cells actually changed.
        changed = []
        for cell in order:
            old_value = cell._value
            cell._value = cell._compute()
            if cell._value != old_value:
                changed.append(cell)

        # Fire callbacks only for cells whose value differs from the
        # previous stable state.
        for cell in changed:
            for callback in cell._callbacks:
                callback(cell._value)


class InputCell(_Cell):
    def __init__(self, initial_value):
        super().__init__()
        self._value = initial_value

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        self._propagate()

    def _compute(self):
        return self._value


class ComputeCell(_Cell):
    def __init__(self, inputs, compute_function):
        super().__init__()
        self._inputs = list(inputs)
        self._compute_function = compute_function
        for input_cell in self._inputs:
            input_cell.add_dependent(self)
        self._value = self._compute()

    def _compute(self):
        return self._compute_function([cell.value for cell in self._inputs])

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

